323	test_p1_deflated(){
324	  // create  grid, ranges, basis
325	  double lower[] = { 0.0, -1.5 }, upper[] = { 1.5, 1.5 };
326	  int cells[] = { 8, 16 };
327	  struct gkyl_rect_grid grid;
328	  gkyl_rect_grid_init(&grid, 2, lower, upper, cells);
329	  struct gkyl_range local, local_ext;
330	  int nghost[GKYL_MAX_CDIM] = { 1, 1 };
331	  gkyl_create_grid_ranges(&grid, nghost, &local_ext, &local);
332	  int poly_order = 1;
333	  struct gkyl_basis basis;
334	  gkyl_cart_modal_serendip(&basis, 2, poly_order);
335	  bool use_gpu = false;
336	#ifdef GKYL_HAVE_CUDA
337	  use_gpu = true;
338	  struct gkyl_basis *basis_on_dev = gkyl_cu_malloc(sizeof(struct gkyl_basis));
339	  gkyl_cart_modal_serendip_cu_dev(basis_on_dev, 2, poly_order);
340	#else
341	  struct gkyl_basis *basis_on_dev = &basis;
342	#endif
343	
344	  // Project Initial Function
345	  struct gkyl_array *funcdg = gkyl_array_new(GKYL_DOUBLE, basis.num_basis, local_ext.volume);
346	  gkyl_eval_on_nodes *eon = gkyl_eval_on_nodes_new(&grid, &basis, 1, &proj_func, 0);
347	  gkyl_eval_on_nodes_advance(eon, 0.0, &local, funcdg);
348	  // gkyl_grid_sub_array_write(&grid, &local, 0, funcdg, "proj_func.gkyl");
349	#ifdef GKYL_HAVE_CUDA
350	  struct gkyl_array *funcdg_dev = gkyl_array_cu_dev_new(GKYL_DOUBLE, basis.num_basis, local_ext.volume);
351	  gkyl_array_copy(funcdg_dev, funcdg);
352	#else
353	  struct gkyl_array *funcdg_dev = funcdg;
354	#endif
355	
356	  // Construct Nodal range, field, and nodal ops object
357	  int nodes[3] = { 1, 1, 1 };
358	  for (int d=0; d<grid.ndim; ++d)
359	    nodes[d] = grid.cells[d] + 1;
360	  struct gkyl_range nrange;
361	  gkyl_range_init_from_shape(&nrange, grid.ndim, nodes);
362	  struct gkyl_array* nodal_fld = gkyl_array_new(GKYL_DOUBLE, grid.ndim, nrange.volume);
363	#ifdef GKYL_HAVE_CUDA
364	  struct gkyl_array *nodal_fld_dev = gkyl_array_cu_dev_new(GKYL_DOUBLE, grid.ndim, nrange.volume);
365	#else
366	  struct gkyl_array *nodal_fld_dev = nodal_fld;
367	#endif
368	  struct gkyl_nodal_ops *n2m = gkyl_nodal_ops_new(&basis, &grid, use_gpu);
369	
370	  // Create deflated 1d grid, ranges, basis, nodal range
371	  struct gkyl_rect_grid deflated_grid;
372	  struct gkyl_basis deflated_basis;
373	  struct gkyl_range deflated_local, deflated_local_ext;
374	  double deflated_lower[1] = { grid.lower[0]}, deflated_upper[1] = { grid.upper[0]};
375	  int deflated_cells[1] = { grid.cells[0] };
376	  gkyl_rect_grid_init(&deflated_grid, 1, deflated_lower, deflated_upper, deflated_cells);
377	  int deflated_nghost[GKYL_MAX_CDIM] = { 1 };
378	  gkyl_create_grid_ranges(&deflated_grid, deflated_nghost, &deflated_local_ext, &deflated_local);
379	  gkyl_cart_modal_serendip(&deflated_basis, 1, poly_order);
380	#ifdef GKYL_HAVE_CUDA
381	  use_gpu = true;
382	  struct gkyl_basis *deflated_basis_on_dev = gkyl_cu_malloc(sizeof(struct gkyl_basis));
383	  gkyl_cart_modal_serendip_cu_dev(deflated_basis_on_dev, deflated_grid.ndim, poly_order);
384	#else
385	  struct gkyl_basis *deflated_basis_on_dev = &deflated_basis;
386	#endif
387	  int deflated_nodes[1];
388	  for (int d=0; d<deflated_grid.ndim; ++d)
389	    deflated_nodes[d] = deflated_grid.cells[d] + 1;
390	  struct gkyl_range deflated_nrange;
391	  gkyl_range_init_from_shape(&deflated_nrange, deflated_grid.ndim, deflated_nodes);
392	
393	  // Create deflated modal field 
394	  struct gkyl_array *deflated_funcdg = gkyl_array_new(GKYL_DOUBLE, deflated_basis.num_basis, local_ext.volume);
395	#ifdef GKYL_HAVE_CUDA
396	  struct gkyl_array *deflated_funcdg_dev = gkyl_array_cu_dev_new(GKYL_DOUBLE, deflated_basis.num_basis, local_ext.volume);
397	#else
398	  struct gkyl_array *deflated_funcdg_dev = deflated_funcdg;
399	#endif
400	
401	  // Created deflator objects and 1d nodal ops object
402	  struct gkyl_deflate_zsurf *deflator_lo = gkyl_deflate_zsurf_new(&basis, &deflated_basis, 0, use_gpu);
403	  struct gkyl_deflate_zsurf *deflator_up = gkyl_deflate_zsurf_new(&basis, &deflated_basis, 1, use_gpu);
404	  struct gkyl_nodal_ops *n2m_1d = gkyl_nodal_ops_new(&deflated_basis, &deflated_grid, use_gpu);
405	
406	  // Loop along last dim (z) and call the 1d deflator to populate the 2d nodal field
407	  for(int zidx = local.lower[1]; zidx <= local.upper[1]; zidx++){
408	    gkyl_deflate_zsurf_advance(deflator_lo, zidx, &local, &deflated_local, funcdg_dev, deflated_funcdg_dev, 1);
409	    gkyl_nodal_ops_m2n_deflated(n2m_1d, deflated_basis_on_dev, &deflated_grid, &nrange, &deflated_nrange, &deflated_local, 1, nodal_fld_dev, deflated_funcdg_dev, zidx-1);
410	    if (zidx == local.upper[1]) {
411	      gkyl_deflate_zsurf_advance(deflator_up, zidx, &local, &deflated_local, funcdg_dev, deflated_funcdg_dev, 1);
412	      gkyl_nodal_ops_m2n_deflated(n2m_1d, deflated_basis_on_dev, &deflated_grid, &nrange, &deflated_nrange, &deflated_local, 1, nodal_fld_dev, deflated_funcdg_dev, zidx);
413	    }
414	  }
415	
416	  // Create output field
417	  struct gkyl_array *funcdg2 = gkyl_array_new(GKYL_DOUBLE, basis.num_basis, local_ext.volume);
418	#ifdef GKYL_HAVE_CUDA
419	  struct gkyl_array *funcdg2_dev = gkyl_array_cu_dev_new(GKYL_DOUBLE, basis.num_basis, local_ext.volume);
420	#else
421	  struct gkyl_array *funcdg2_dev = funcdg2;
422	#endif
423	
424	  // Transform back to modal
425	  gkyl_nodal_ops_n2m(n2m, basis_on_dev, &grid, &nrange, &local, 1, nodal_fld_dev, funcdg2_dev, false);
426	#ifdef GKYL_HAVE_CUDA
427	  gkyl_array_copy(funcdg2, funcdg2_dev);
428	#endif
429	  check_same(local, basis, funcdg, funcdg2);
430	  // gkyl_grid_sub_array_write(&grid, &local, 0, funcdg2, "proj_func2.gkyl");
431	
432	#ifdef GKYL_HAVE_CUDA
433	  gkyl_cu_free(basis_on_dev);
434	  gkyl_array_release(funcdg_dev);
435	  gkyl_array_release(deflated_funcdg_dev);
436	  gkyl_array_release(funcdg2_dev);
437	  gkyl_array_release(nodal_fld_dev);
438	#endif
439	  gkyl_array_release(funcdg);
440	  gkyl_array_release(deflated_funcdg);
441	  gkyl_array_release(funcdg2);
442	  gkyl_array_release(nodal_fld);
443	
444	  gkyl_eval_on_nodes_release(eon);
445	  gkyl_nodal_ops_release(n2m);
446	  gkyl_nodal_ops_release(n2m_1d);
447	  gkyl_deflate_zsurf_release(deflator_lo);
448	  gkyl_deflate_zsurf_release(deflator_up);
449	
450	}
