584	test_p2_btype(enum gkyl_basis_type basis_type){
585	  // create  grid
586	  double lower[] = { 0.0, -1.5 }, upper[] = { 1.5, 1.5 };
587	  // as ellipitical surfaces are exact, we only need 1 cell in each
588	  // direction
589	  int cells[] = { 8, 16 };
590	
591	
592	  int poly_order = 2;
593	  struct gkyl_rect_grid grid;
594	  gkyl_rect_grid_init(&grid, 2, lower, upper, cells);
595	
596	  //  ranges
597	  struct gkyl_range local, local_ext;
598	  int nghost[GKYL_MAX_CDIM] = { 1, 1 };
599	  gkyl_create_grid_ranges(&grid, nghost, &local_ext, &local);
600	
601	  //  basis function
602	  struct gkyl_basis basis;
603	  if(basis_type == GKYL_BASIS_MODAL_SERENDIPITY)
604	    gkyl_cart_modal_serendip(&basis, 2, poly_order);
605	  if(basis_type == GKYL_BASIS_MODAL_TENSOR)
606	    gkyl_cart_modal_tensor(&basis, 2, poly_order);
607	
608	  struct gkyl_array *funcdg = gkyl_array_new(GKYL_DOUBLE, basis.num_basis, local_ext.volume);
609	  
610	  gkyl_eval_on_nodes *eon = gkyl_eval_on_nodes_new(&grid, &basis, 1, &proj_func, 0);
611	  gkyl_eval_on_nodes_advance(eon, 0.0, &local, funcdg);
612	  gkyl_eval_on_nodes_release(eon);
613	  // gkyl_grid_sub_array_write(&grid, &local, 0, funcdg, "proj_func.gkyl");
614	
615	  int nodes[3] = { 1, 1, 1 };
616	                   
617	  for (int d=0; d<grid.ndim; ++d)
618	    nodes[d] = 2*(grid.cells[d]) + 1;
619	
620	  struct gkyl_range nrange;
621	  gkyl_range_init_from_shape(&nrange, grid.ndim, nodes);
622	
623	
624	  struct gkyl_array* nodal_fld = gkyl_array_new(GKYL_DOUBLE, grid.ndim, nrange.volume);
625	  struct gkyl_nodal_ops *n2m = gkyl_nodal_ops_new(&basis, &grid, false);
626	  gkyl_nodal_ops_m2n(n2m, &basis, &grid, &nrange, &local, 1, nodal_fld, funcdg, false);
627	
628	  struct gkyl_array *funcdg2 = gkyl_array_new(GKYL_DOUBLE, basis.num_basis, local_ext.volume);
629	  gkyl_nodal_ops_n2m(n2m, &basis, &grid, &nrange, &local, 1, nodal_fld, funcdg2, false);
630	  gkyl_nodal_ops_release(n2m);
631	  check_same(local, basis, funcdg, funcdg2);
632	  // gkyl_grid_sub_array_write(&grid, &local, 0, funcdg2, "proj_func2.gkyl");
633	
634	  gkyl_array_release(funcdg);
635	  gkyl_array_release(funcdg2);
636	  gkyl_array_release(nodal_fld);
637	  
638	}
